-- Corrects public.court_form_library against the official Ontario court forms
-- list (ontariocourtforms.on.ca, fetched 2026-10-04 into
-- src/lib/content-library/forms/officialFormLinks.json on branch
-- claude/official-form-links: 430 forms -- Small Claims 46, civil 240, family 144).
--
--   renumber    63 rows  form_number did not match the form in the file. The number
--                         is read from the row's own file name (e.g.
--                         rcp-e-2-2a-0624.docx was "Form 2", is "Form 2.2A";
--                         scr-01a1-jan14 was "Form 1A", is "Form 1A.1").
--                         Family 8.0.1 is stored as "Form 8.0.1" (the
--                         regulation's numbering, which the forms guide uses),
--                         though the forms site writes it "8.01".
--   retitle    149 rows  official_title set to the official title for the row's
--                         number: generic labels ("Child Protection Form" on
--                         Form 29A, "Adoption Form" on Form 30), another
--                         form's title (Small Claims 20C "Notice of
--                         Examination"), number fragments ("2A Request for
--                         Clerk's Order on Consent") and truncations ("Claim").
--   deactivate   1 row   not an official form: the family "Notice To Profession"
--                         stored as "Form 1". is_active = false; nothing deleted.
--   stale        3 rows  the stored file is older than the current official
--                         version (civil 53, family 26B, family 32.1). The file
--                         is not changed; form_revision_or_effective_at says a
--                         newer version exists and official_source_url points
--                         at the official file.
--   insert      59 rows  official forms with no active row: the 54 estates forms
--                         (Rules 74, 74.1, 75, 75.1 -- including 75.2, which is
--                         on the forms site though not in the vendored table of
--                         forms) and the 5 new family forms (1.4, 1.4A,
--                         33D.1-33D.3). file_path is NULL: the catalogue links
--                         to the official file and does not store a copy.
--
-- GENERATED from supabase/snapshots/20260822_catalogue_data_snapshot.sql (the
-- 2026-08-22 capture), not from the live database. Every UPDATE is guarded on
-- the row's identity AND the old value it replaces, so a row production has
-- already changed is skipped, not overwritten.
--
-- Row identity is "id" AND "file_path". In the snapshot only 136 of the 723
-- rows have an id; the other 587 have id NULL (the table has no primary key).
-- file_path carries the table's only unique constraint
-- (court_form_library_file_path_unique) and is set on every row, so each
-- UPDATE names its row as id = '<uuid>' AND file_path = '<path>', or, where
-- the snapshot has no id, id IS NULL AND file_path = '<path>'. Either form
-- matches at most one row. Every INSERT is skipped when an active
-- row with the same court_type and form_number already exists. Re-running the
-- file is a no-op. Rows left alone on purpose, and why, are in the change log
-- that accompanies this file (changes.md).
--
-- *** NOT APPLIED BY ANYTHING IN THIS REPOSITORY ***
--
-- The site owner applies it, staging (icpvzwxyjsdgyqfkwycw) before production
-- (fddlpnibovkkkgboabqb), after taking a backup. CLAUDE.md section 6: production
-- has no automatic backups; take a `supabase db dump` and check its byte count.

BEGIN;

